def calcul(a, operateur, b):
    if operateur == "+":
        return a + b
    if operateur == "-":
        return a - b
    if operateur == "*":
        return a * b
    if operateur == "/":
        if b == 0:
            return "erreur"
        return a / b
    return "operateur inconnu"

print(calcul(3, "+", 4))
print(calcul(3, "*", 4))
print(calcul(5, "/", 2))
print(calcul(5, "/", 0))
